export function cx(...parts: (string | false | null | undefined)[]): string {
  return parts.filter(Boolean).join(' ')
}

export const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n))

export const pct = (x: number, digits = 1) => `${(x * 100).toFixed(digits)}%`

export function formatHours(h: number): string {
  return h < 1 ? `${Math.round(h * 60)}m` : `${h.toFixed(1)}h`
}

export function formatWhen(iso: string): string {
  const d = new Date(iso)
  return Number.isNaN(d.getTime()) ? iso : d.toISOString().replace('T', ' ').slice(0, 16) + 'Z'
}

// Small scale and format helpers shared by the chart-like components. No dependencies.

export type Scale = ((v: number) => number) & { invert: (px: number) => number; domain: [number, number]; range: [number, number] }

export function linear(domain: [number, number], range: [number, number]): Scale {
  const [d0, d1] = domain
  const [r0, r1] = range
  const span = d1 - d0 || 1
  const f = ((v: number) => r0 + ((v - d0) / span) * (r1 - r0)) as Scale
  f.invert = (px: number) => d0 + ((px - r0) / (r1 - r0 || 1)) * span
  f.domain = domain
  f.range = range
  return f
}

/** Round tick values that fit in [min, max], about `count` of them (1, 2, 5 times a power of ten). */
export function niceTicks(min: number, max: number, count = 6): number[] {
  if (!(max > min)) return [min]
  const raw = (max - min) / Math.max(count, 1)
  const pow = Math.pow(10, Math.floor(Math.log10(raw)))
  const err = raw / pow
  const step = (err >= 7.5 ? 10 : err >= 3.5 ? 5 : err >= 1.5 ? 2 : 1) * pow
  const out: number[] = []
  for (let v = Math.ceil(min / step) * step; v <= max + step * 1e-9; v += step) out.push(Math.round(v / step) * step)
  return out
}

/** 850 ms, 1.20 s, 2 m 05 s. */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms)) return ''
  if (ms === 0) return '0'
  const abs = Math.abs(ms)
  if (abs < 1) return `${(ms * 1000).toFixed(0)} µs`
  if (abs < 1000) return `${Number(ms.toFixed(abs < 10 ? 1 : 0))} ms`
  if (abs < 60_000) return `${(ms / 1000).toFixed(abs < 10_000 ? 2 : 1)} s`
  const sign = ms < 0 ? '-' : ''
  if (abs >= 86_400_000) return `${sign}${Math.floor(abs / 86_400_000)} d ${Math.floor((abs % 86_400_000) / 3_600_000)} h`
  if (abs >= 3_600_000) return `${sign}${Math.floor(abs / 3_600_000)} h ${String(Math.round((abs % 3_600_000) / 60_000)).padStart(2, '0')} m`
  const m = Math.floor(abs / 60_000)
  const s = Math.round((abs % 60_000) / 1000)
  return `${ms < 0 ? '-' : ''}${m} m ${String(s).padStart(2, '0')} s`
}

export const formatCount = (n: number) => new Intl.NumberFormat('en', { notation: n >= 100_000 ? 'compact' : 'standard', maximumFractionDigits: 1 }).format(n)
export const formatUsd = (n: number) => (n < 0.01 && n > 0 ? '<$0.01' : new Intl.NumberFormat('en', { style: 'currency', currency: 'USD' }).format(n))

/** Cycles through the categorical palette defined as --ic-c1..8 in styles.css. */
export const swatch = (i: number) => `var(--ic-c${(((i % 8) + 8) % 8) + 1})`

export const clampNum = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n))

import { useEffect, useRef, useState, type RefObject } from 'react'

/** Width of an element, kept current with ResizeObserver. Returns `initial` on the server and before first measure. */
export function useWidth<T extends HTMLElement>(initial = 720): [RefObject<T | null>, number] {
  const ref = useRef<T | null>(null)
  const [width, setWidth] = useState(initial)
  useEffect(() => {
    const el = ref.current
    if (!el) return
    const measure = () => setWidth(Math.max(240, Math.round(el.getBoundingClientRect().width)))
    measure()
    if (typeof ResizeObserver === 'undefined') return
    const ro = new ResizeObserver(measure)
    ro.observe(el)
    return () => ro.disconnect()
  }, [])
  return [ref, width]
}

/** Copies text and reports success briefly. Safe when the clipboard is unavailable. */
export function useCopy(): [boolean, (text: string) => void] {
  const [done, setDone] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  return [
    done,
    (text) => {
      navigator.clipboard?.writeText(text).then(() => {
        setDone(true)
        clearTimeout(timer.current)
        timer.current = setTimeout(() => setDone(false), 1400)
      }, () => undefined)
    },
  ]
}

// Exact binomial machinery in log space, stable for n in the thousands. Ported from the failure calculus
// so a client statistician can audit it in one file.

const logFactCache: number[] = [0, 0]
function logFact(n: number): number {
  for (let i = logFactCache.length; i <= n; i++) logFactCache[i] = (logFactCache[i - 1] ?? 0) + Math.log(i)
  return logFactCache[n] ?? 0
}
const logChoose = (n: number, k: number) => logFact(n) - logFact(k) - logFact(n - k)

function binomPmf(k: number, n: number, p: number): number {
  if (p <= 0) return k === 0 ? 1 : 0
  if (p >= 1) return k === n ? 1 : 0
  return Math.exp(logChoose(n, k) + k * Math.log(p) + (n - k) * Math.log(1 - p))
}
function binomCdf(k: number, n: number, p: number): number {
  let s = 0
  for (let i = 0; i <= k; i++) s += binomPmf(i, n, p)
  return Math.min(1, s)
}
const binomTailGE = (k: number, n: number, p: number) => (k <= 0 ? 1 : 1 - binomCdf(k - 1, n, p))

export type Interval = { lower: number; upper: number }

/** Clopper-Pearson exact interval for passes out of n, found by bisection on the binomial CDF. */
export function clopperPearson(passes: number, n: number, confidence = 0.95): Interval {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer')
  if (!Number.isInteger(passes) || passes < 0 || passes > n) throw new RangeError('passes must be an integer from 0 to n')
  const alpha = 1 - confidence
  const bisect = (isLow: (p: number) => boolean) => {
    let lo = 0
    let hi = 1
    for (let i = 0; i < 100; i++) {
      const mid = (lo + hi) / 2
      if (isLow(mid)) lo = mid
      else hi = mid
    }
    return (lo + hi) / 2
  }
  const lower = passes === 0 ? 0 : bisect((p) => binomTailGE(passes, n, p) <= alpha / 2)
  const upper = passes === n ? 1 : bisect((p) => binomCdf(passes, n, p) > alpha / 2)
  return { lower, upper }
}

/** Upper bound on the true failure rate when zero failures were seen in n cases: 1 - alpha^(1/n). */
export function zeroFailureUpperBound(n: number, confidence = 0.95): number {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer')
  return 1 - Math.pow(1 - confidence, 1 / n)
}

/**
 * Exact McNemar p-value (two-sided) for a paired re-test on the same case set. Under no change, the cases
 * that flipped split Binomial(regressed + improved, 0.5).
 */
export function mcnemarExact(regressed: number, improved: number): number {
  if (![regressed, improved].every((x) => Number.isInteger(x) && x >= 0)) throw new RangeError('counts must be non-negative integers')
  const n = regressed + improved
  if (n === 0) return 1
  return Math.min(1, 2 * binomCdf(Math.min(regressed, improved), n, 0.5))
}

/* incised: plain CSS, no Tailwind. Theme by overriding the --ic-* variables, or inherit a shadcn theme:
   --background, --foreground, --muted-foreground, --border and --primary are read when present. */
.ic {
  --ic-bg: var(--background, #ffffff);
  --ic-fg: var(--foreground, #16181d);
  --ic-muted: var(--muted-foreground, #5d6470);
  --ic-line: var(--border, #e3e5ea);
  --ic-accent: var(--primary, #1d232b);
  --ic-surface: color-mix(in srgb, var(--ic-fg) 4%, var(--ic-bg));
  --ic-good: #1f7a4d;
  --ic-warn: #a35a00;
  --ic-bad: #b3261e;
  --ic-radius: 10px;
  --ic-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--ic-fg);
  background: var(--ic-bg);
  border: 1px solid var(--ic-line);
  border-radius: var(--ic-radius);
  padding: 16px;
  font: 14px/1.45 system-ui, -apple-system, 'Segoe UI', sans-serif;
  box-sizing: border-box;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) .ic { --ic-good: #5fcf94; --ic-warn: #f0b255; --ic-bad: #ff8a80; }
}
:root[data-theme='dark'] .ic { --ic-good: #5fcf94; --ic-warn: #f0b255; --ic-bad: #ff8a80; }
.ic *, .ic *::before, .ic *::after { box-sizing: border-box; }
.ic-title { margin: 0 0 12px; font-size: 15px; font-weight: 600; }
.ic-sub { color: var(--ic-muted); font-size: 12px; }
.ic-mono { font-family: var(--ic-mono); }
.ic-list { list-style: none; margin: 0; padding: 0; }
.ic-pill { display: inline-flex; align-items: center; gap: 4px; padding: 1px 8px; border-radius: 999px; font-size: 12px; border: 1px solid var(--ic-line); background: var(--ic-surface); }
.ic-pill[data-tone='good'] { color: var(--ic-good); border-color: currentColor; }
.ic-pill[data-tone='warn'] { color: var(--ic-warn); border-color: currentColor; }
.ic-pill[data-tone='bad'] { color: var(--ic-bad); border-color: currentColor; }

/* Swimlane */
.ic-lane { display: grid; grid-template-columns: 110px 1fr; gap: 12px; padding: 8px 0; border-top: 1px solid var(--ic-line); }
.ic-lane:first-of-type { border-top: 0; }
.ic-lane-owner { font-weight: 600; font-size: 13px; }
.ic-steps { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.ic-step { padding: 4px 10px; border-radius: 6px; border: 1px solid var(--ic-line); background: var(--ic-surface); }
.ic-step[data-waiting='true'] { border-color: var(--ic-warn); color: var(--ic-warn); }
.ic-arrow { color: var(--ic-muted); }

/* Trail */
.ic-stop { position: relative; display: grid; grid-template-columns: 20px 1fr auto; gap: 10px; padding-bottom: 14px; }
.ic-stop::before { content: ''; position: absolute; left: 4px; top: 14px; bottom: 0; width: 1px; background: var(--ic-line); }
.ic-stop:last-child::before { display: none; }
.ic-dot { width: 9px; height: 9px; margin-top: 5px; border-radius: 50%; background: var(--ic-accent); }
.ic-dot[data-wait='true'] { background: var(--ic-warn); }

/* Bars (Bottlenecks, Funnel) */
.ic-row { display: grid; grid-template-columns: minmax(80px, 160px) 1fr auto; gap: 10px; align-items: center; padding: 4px 0; }
.ic-bar { height: 10px; border-radius: 5px; background: var(--ic-surface); overflow: hidden; }
.ic-bar > span { display: block; height: 100%; background: var(--ic-accent); border-radius: 5px; }
.ic-bar > span[data-top='true'] { background: var(--ic-warn); }
.ic-kept { margin: 0 0 0 4px; font-size: 12px; color: var(--ic-muted); }

/* Priority */
.ic-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.ic-cell { border: 1px solid var(--ic-line); border-radius: 8px; padding: 10px; min-height: 84px; background: var(--ic-surface); }
.ic-cell h4 { margin: 0 0 6px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ic-muted); }
.ic-cell ul { margin: 0; padding-left: 16px; }

/* Compare */
.ic-compare { display: grid; grid-template-columns: 120px 1fr 1fr; gap: 0; border: 1px solid var(--ic-line); border-radius: 8px; overflow: hidden; }
.ic-compare > div { padding: 8px 10px; border-top: 1px solid var(--ic-line); }
.ic-compare > .ic-head { border-top: 0; background: var(--ic-surface); font-weight: 600; font-size: 12px; }
.ic-compare > .ic-label { color: var(--ic-muted); }

/* Records */
.ic-head-row { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; margin-bottom: 8px; }
.ic-dl { display: grid; grid-template-columns: max-content 1fr; gap: 4px 12px; margin: 8px 0 0; }
.ic-dl dt { color: var(--ic-muted); }
.ic-dl dd { margin: 0; }
.ic-verdict { display: flex; align-items: center; gap: 10px; font-size: 16px; font-weight: 600; }
.ic-verdict[data-ok='true'] { color: var(--ic-good); }
.ic-verdict[data-ok='false'] { color: var(--ic-bad); }
.ic-verdict[data-ok='unknown'] { color: var(--ic-muted); }
.ic-problems { margin: 8px 0 0; padding-left: 18px; color: var(--ic-bad); }
.ic-event { display: grid; grid-template-columns: 28px 1fr auto; gap: 10px; padding: 8px 0; border-top: 1px solid var(--ic-line); }
.ic-event:first-child { border-top: 0; }
.ic-event[data-flag='bad'] .ic-evtype { color: var(--ic-bad); }
.ic-event[data-flag='warn'] .ic-evtype { color: var(--ic-warn); }
.ic-event[data-flag='good'] .ic-evtype { color: var(--ic-good); }
.ic-evtype { font-weight: 600; }
.ic-track { position: relative; height: 12px; border-radius: 6px; background: var(--ic-surface); border: 1px solid var(--ic-line); margin: 10px 0 6px; }
.ic-band { position: absolute; top: 0; bottom: 0; background: color-mix(in srgb, var(--ic-accent) 30%, transparent); border-radius: 6px; }
.ic-mark { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--ic-fg); }
.ic-mark[data-kind='threshold'] { background: var(--ic-warn); }
.ic-progress { height: 8px; border-radius: 4px; background: var(--ic-surface); overflow: hidden; margin: 8px 0; }
.ic-progress > span { display: block; height: 100%; background: var(--ic-accent); }
.ic-progress[data-state='late'] > span, .ic-progress[data-state='bad'] > span { background: var(--ic-bad); }
.ic-progress[data-state='ok'] > span { background: var(--ic-good); }

/* Controls */
.ic-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.ic-chip, .ic-sortbtn, .ic-twist { font: inherit; color: inherit; background: transparent; border: 1px solid var(--ic-line); border-radius: 999px; padding: 2px 10px; cursor: pointer; }
.ic-chip[aria-pressed='true'] { background: var(--ic-accent); color: var(--ic-bg); border-color: var(--ic-accent); }
.ic-sortbtn { border: 0; padding: 0; font-weight: 600; border-radius: 4px; }
.ic-twist { border: 0; width: 18px; padding: 0; display: inline-block; text-align: center; }
.ic :is(.ic-chip, .ic-sortbtn, .ic-twist, select):focus-visible { outline: 2px solid var(--ic-accent); outline-offset: 2px; }
.ic select { font: inherit; color: inherit; background: var(--ic-bg); border: 1px solid var(--ic-line); border-radius: 6px; padding: 2px 6px; margin-left: 4px; }
.ic-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; padding: 0; }
.ic-scroll { overflow-x: auto; }

/* Table */
.ic-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.ic-table th, .ic-table td { text-align: left; padding: 6px 10px; border-top: 1px solid var(--ic-line); vertical-align: top; }
.ic-table thead th { border-top: 0; font-size: 12px; color: var(--ic-muted); }
.ic-table tbody th { font-weight: 500; }
.ic-table tfoot th, .ic-table tfoot td { border-top: 2px solid var(--ic-line); }
.ic-table td[data-pass='true'] { color: var(--ic-good); }
.ic-table td[data-pass='false'] { color: var(--ic-bad); background: color-mix(in srgb, var(--ic-bad) 8%, transparent); }
.ic-table tr[data-flip='regressed'] > th { box-shadow: inset 3px 0 var(--ic-bad); }
.ic-table tr[data-flip='improved'] > th { box-shadow: inset 3px 0 var(--ic-good); }
.ic-compare-bar { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin: 12px 0 8px; }

/* AgentTrace */
.ic-span { display: grid; grid-template-columns: minmax(150px, 38%) 1fr 64px; gap: 8px; align-items: center; padding: 4px 0; border-top: 1px solid var(--ic-line); }
.ic-span:first-child { border-top: 0; }
.ic-span-name { display: flex; align-items: center; gap: 6px; min-width: 0; }
.ic-kind { font-size: 11px; padding: 0 6px; border-radius: 4px; background: var(--ic-surface); color: var(--ic-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.ic-wf { position: relative; height: 12px; background: var(--ic-surface); border-radius: 3px; }
.ic-wf > span { position: absolute; top: 0; bottom: 0; background: var(--ic-accent); border-radius: 3px; }
.ic-span[data-status='error'] .ic-wf > span { background: var(--ic-bad); }
.ic-span[data-status='blocked'] .ic-wf > span { background: var(--ic-warn); }
.ic-span-detail { grid-column: 1 / -1; padding-left: 24px; }

/* EvidenceDiff */
.ic-diff { border: 1px solid var(--ic-line); border-radius: 8px; overflow: hidden; font-size: 12.5px; }
.ic-diff-head, .ic-diff-row { display: grid; grid-template-columns: 1fr 1fr; }
.ic-diff-head { background: var(--ic-surface); font-weight: 600; font-size: 12px; }
.ic-diff-head > span { padding: 6px 10px; }
.ic-diff pre, .ic-diff-uni pre { margin: 0; padding: 2px 10px; font-family: var(--ic-mono); white-space: pre-wrap; word-break: break-word; min-height: 1.45em; }
.ic-diff-row > pre + pre { border-left: 1px solid var(--ic-line); }
.ic-diff-uni { border: 1px solid var(--ic-line); border-radius: 8px; overflow: hidden; font-size: 12.5px; }
.ic [data-kind='add'] { background: color-mix(in srgb, var(--ic-good) 14%, transparent); }
.ic [data-kind='del'] { background: color-mix(in srgb, var(--ic-bad) 14%, transparent); }
.ic-word { color: inherit; border-radius: 2px; }
.ic-word[data-kind='add'] { background: color-mix(in srgb, var(--ic-good) 38%, transparent); }
.ic-word[data-kind='del'] { background: color-mix(in srgb, var(--ic-bad) 38%, transparent); }

/* ApprovalFlow */
.ic-flow { display: block; max-width: none; }
.ic-flow-node { fill: var(--ic-surface); stroke: var(--ic-line); stroke-width: 1.5; }
.ic-flow-text { fill: var(--ic-fg); font: 600 12.5px system-ui, sans-serif; }
.ic-flow-tag { fill: var(--ic-muted); font: 600 8px system-ui, sans-serif; letter-spacing: 0.06em; }
.ic-flow-edge { fill: none; stroke: var(--ic-muted); stroke-width: 1.5; }
.ic-flow-arrow { fill: var(--ic-muted); }
.ic-flow-label { fill: var(--ic-muted); font: 11px system-ui, sans-serif; paint-order: stroke; stroke: var(--ic-bg); stroke-width: 4px; stroke-linejoin: round; }
.ic-flow g[data-kind='gate'] .ic-flow-node { stroke-dasharray: 5 3; }
.ic-flow g[data-state='done'] .ic-flow-node { stroke: var(--ic-good); }
.ic-flow g[data-state='active'] .ic-flow-node { stroke: var(--ic-accent); stroke-width: 2.5; fill: color-mix(in srgb, var(--ic-accent) 14%, var(--ic-bg)); }

/* ChainGraph */
.ic-chain { display: flex; align-items: stretch; padding: 4px 0 8px; }
.ic-block { flex: 0 0 204px; border: 1px solid var(--ic-line); border-radius: 8px; padding: 8px 10px; display: grid; gap: 2px; align-content: start; background: var(--ic-surface); }
.ic-block .ic-pill { white-space: nowrap; justify-self: start; margin-top: 4px; }
.ic-block[data-bad='true'] { border-color: var(--ic-bad); }
.ic-link { flex: 0 0 32px; align-self: center; height: 2px; background: var(--ic-good); position: relative; }
.ic-link[data-ok='false'] { background: repeating-linear-gradient(90deg, var(--ic-bad) 0 4px, transparent 4px 8px); }
.ic-link > span { position: absolute; top: -18px; left: 50%; transform: translateX(-50%); color: var(--ic-bad); font-weight: 700; }

/* Receipt */
.ic-receipt-foot { margin-top: 12px; padding-top: 10px; border-top: 1px dashed var(--ic-line); display: grid; gap: 8px; }
@media print { .ic { border-color: #999; break-inside: avoid; } }

/* Categorical palette, used by anything that colours by kind */
.ic { --ic-c1: #2f6fdb; --ic-c2: #d9822b; --ic-c3: #2a9d6f; --ic-c4: #8a5cd1; --ic-c5: #cf4b6b; --ic-c6: #1f9fb3; --ic-c7: #a5902a; --ic-c8: #6b7480; font-variant-numeric: tabular-nums; }
@media (prefers-color-scheme: dark) { :root:not([data-theme='light']) .ic { --ic-c1: #6ea0ff; --ic-c2: #f0a85a; --ic-c3: #5fcf94; --ic-c4: #b896f0; --ic-c5: #f27f9a; --ic-c6: #5ccbdc; --ic-c7: #d8c35a; --ic-c8: #9aa1ab; } }
:root[data-theme='dark'] .ic { --ic-c1: #6ea0ff; --ic-c2: #f0a85a; --ic-c3: #5fcf94; --ic-c4: #b896f0; --ic-c5: #f27f9a; --ic-c6: #5ccbdc; --ic-c7: #d8c35a; --ic-c8: #9aa1ab; }
.ic-num { text-align: right !important; }
.ic-ell { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.ic-dot-kind { display: inline-block; width: 9px; height: 9px; border-radius: 2px; flex: none; }
.ic-linkbtn { font: inherit; color: var(--ic-accent); background: none; border: 0; padding: 0; cursor: pointer; text-decoration: underline; text-underline-offset: 2px; }
.ic-input { font: inherit; color: inherit; background: var(--ic-bg); border: 1px solid var(--ic-line); border-radius: 8px; padding: 4px 10px; min-width: 160px; }
.ic-input:focus-visible, .ic-trace-body:focus-visible { outline: 2px solid var(--ic-accent); outline-offset: 2px; }
.ic-chip:disabled { opacity: 0.45; cursor: default; }
.ic-tabs { display: inline-flex; background: var(--ic-surface); border-radius: 8px; padding: 2px; gap: 2px; }
.ic-tab { font: inherit; font-size: 13px; color: var(--ic-muted); background: transparent; border: 0; border-radius: 6px; padding: 3px 10px; cursor: pointer; }
.ic-tab[aria-selected='true'] { background: var(--ic-bg); color: var(--ic-fg); box-shadow: 0 1px 2px color-mix(in srgb, var(--ic-fg) 14%, transparent); }
.ic-tab:disabled { opacity: 0.4; cursor: default; }
.ic-tab:focus-visible { outline: 2px solid var(--ic-accent); outline-offset: 1px; }
.ic-facts { display: flex; flex-wrap: wrap; gap: 6px 22px; margin: 4px 0 10px; }
.ic-facts > div { display: grid; }
