.ic-tip { position: absolute; z-index: 5; pointer-events: none; min-width: 190px; background: var(--ic-bg); color: var(--ic-fg); border: 1px solid var(--ic-line); border-radius: 8px; padding: 8px 10px; box-shadow: 0 6px 20px color-mix(in srgb, var(--ic-fg) 18%, transparent); font-size: 12.5px; }
