.ic-json-more { background: none; border: 0; color: var(--ic-accent); font: inherit; font-size: 11.5px; cursor: pointer; margin-left: 8px; text-decoration: underline; }

/* DiffViewer */
.ic-add { color: var(--ic-good); font-weight: 600; }
.ic-del { color: var(--ic-bad); font-weight: 600; }
.ic-spacer { flex: 1; }
.ic-statbar { display: inline-flex; gap: 2px; vertical-align: middle; margin-left: 4px; }
