.ic-ftree { display: grid; gap: 2px; width: 230px; align-content: start; position: sticky; top: 8px; font-size: 13px; }
.ic-ftree a { display: flex; justify-content: space-between; gap: 8px; padding: 5px 8px; border-radius: 6px; color: inherit; text-decoration: none; }
