.ic-fcount { font-size: 12px; white-space: nowrap; flex: none; }
.ic-ftree a > .ic-ell { min-width: 0; flex: 1; }
.ic-c-ln { width: 46px; }
.ic-c-sign { width: 18px; }
.ic-files { display: grid; gap: 12px; min-width: 0; }
.ic-file { border: 1px solid var(--ic-line); border-radius: 8px; overflow: hidden; }
