.ic-ln { text-align: right; padding: 0 8px; color: var(--ic-muted); user-select: none; cursor: pointer; font: 12px/1.6 var(--ic-mono); vertical-align: top; background: color-mix(in srgb, var(--ic-fg) 3%, transparent); }
.ic-ln[data-active='true'] { color: var(--ic-fg); background: color-mix(in srgb, var(--ic-warn) 28%, transparent); }
