.ic-sign[data-kind='add'], .ic-code[data-kind='add'] { background: color-mix(in srgb, var(--ic-good) 14%, transparent); }
.ic-sign[data-kind='del'], .ic-code[data-kind='del'] { background: color-mix(in srgb, var(--ic-bad) 14%, transparent); }
.ic-code { padding: 0 8px; white-space: pre-wrap; word-break: break-word; line-height: 1.6; vertical-align: top; }
