.ic-code[data-active='true'] { box-shadow: inset 3px 0 var(--ic-warn); }
.ic-dtable[data-mode='split'] td:nth-child(3) { border-right: 1px solid var(--ic-line); }
.ic-hunk td { background: color-mix(in srgb, var(--ic-c1) 12%, transparent); color: var(--ic-muted); padding: 2px 10px; font-size: 12px; }
.ic-gap td { background: color-mix(in srgb, var(--ic-c1) 7%, transparent); padding: 0; }
.ic-gap button { font: inherit; font-size: 12px; color: var(--ic-muted); background: none; border: 0; width: 100%; text-align: left; padding: 4px 12px; cursor: pointer; }
.ic-gap button:hover { color: var(--ic-fg); background: color-mix(in srgb, var(--ic-c1) 14%, transparent); }
.ic-comment-row td { padding: 6px 12px 8px 60px; background: var(--ic-surface); }
.ic-comment { border: 1px solid var(--ic-line); border-radius: 8px; padding: 8px 10px; background: var(--ic-bg); font-size: 13px; max-width: 560px; }

/* FlowCanvas */
.ic-legendrow { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 12px; color: var(--ic-muted); }
.ic-ldot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-left: 6px; background: var(--ic-line); }
