@media (prefers-reduced-motion: reduce) { .ic-edges g[data-animated='true'] .ic-flow-edge { animation: none; } }
.ic-edge-pill { fill: var(--ic-bg); stroke: var(--ic-line); }
.ic-fnode { position: absolute; font: inherit; color: inherit; text-align: left; background: var(--ic-bg); border: 1.5px solid var(--ic-line); border-radius: 10px; padding: 7px 12px; display: grid; align-content: center; gap: 1px; cursor: pointer; box-shadow: 0 1px 2px color-mix(in srgb, var(--ic-fg) 10%, transparent); transition: opacity 0.15s, box-shadow 0.15s; }
.ic-fnode:hover { box-shadow: 0 3px 10px color-mix(in srgb, var(--ic-fg) 16%, transparent); }
.ic-fnode:focus-visible { outline: 2px solid var(--ic-accent); outline-offset: 2px; }
.ic-fnode[data-kind='gate'] { border-style: dashed; border-color: var(--ic-warn); border-radius: 22px; }
.ic-fnode[data-kind='end'] { border-radius: 29px; }
.ic-fnode[data-kind='start'] { border-radius: 29px; border-color: var(--ic-c3); }
.ic-fnode[data-status='done'] { border-color: var(--ic-good); }
.ic-fnode[data-status='active'] { border-color: var(--ic-c1); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ic-c1) 22%, transparent); }
.ic-fnode[data-status='blocked'] { border-color: var(--ic-bad); background: color-mix(in srgb, var(--ic-bad) 7%, var(--ic-bg)); }
.ic-fnode[data-selected='true'] { box-shadow: 0 0 0 2px var(--ic-accent), 0 4px 14px color-mix(in srgb, var(--ic-fg) 20%, transparent); }
.ic-fnode[data-dim='true'] { opacity: 0.35; }
.ic-fkind { font-size: 10.5px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ic-muted); display: flex; align-items: center; justify-content: space-between; }
.ic-flabel { font-weight: 600; font-size: 13.5px; line-height: 1.25; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ic-handle { position: absolute; top: 50%; width: 9px; height: 9px; margin-top: -4.5px; border-radius: 50%; background: var(--ic-bg); border: 1.5px solid var(--ic-muted); }
.ic-handle[data-side='l'] { left: -5px; } .ic-handle[data-side='r'] { right: -5px; }
.ic-fctl { position: absolute; left: 10px; bottom: 10px; display: flex; border: 1px solid var(--ic-line); border-radius: 8px; overflow: hidden; background: var(--ic-bg); box-shadow: 0 1px 4px color-mix(in srgb, var(--ic-fg) 14%, transparent); }
.ic-fctl button { font: inherit; width: 30px; height: 30px; background: none; border: 0; border-left: 1px solid var(--ic-line); color: inherit; cursor: pointer; }
.ic-fctl button:first-child { border-left: 0; }
.ic-fctl button:hover, .ic-fctl button[aria-pressed='true'] { background: var(--ic-surface); }
.ic-minimap { position: absolute; right: 10px; bottom: 10px; background: var(--ic-bg); border: 1px solid var(--ic-line); border-radius: 8px; box-shadow: 0 1px 4px color-mix(in srgb, var(--ic-fg) 14%, transparent); cursor: pointer; }
.ic-mm-node { fill: var(--ic-muted); opacity: 0.5; }
.ic-mm-node[data-status='done'] { fill: var(--ic-good); opacity: 0.8; } .ic-mm-node[data-status='active'] { fill: var(--ic-c1); opacity: 0.9; } .ic-mm-node[data-status='blocked'] { fill: var(--ic-bad); opacity: 0.9; }
.ic-mm-view { fill: color-mix(in srgb, var(--ic-accent) 10%, transparent); stroke: var(--ic-accent); stroke-width: 1.2; }
.ic-fdetail { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 16px; }
.ic-fdetail .ic-linkbtn { display: block; text-align: left; margin-top: 2px; }
@media (max-width: 640px) { .ic-fdetail { grid-template-columns: 1fr; } }

/* DataGrid */
.ic-dg { position: relative; overflow: auto; border: 1px solid var(--ic-line); border-radius: 10px; background: var(--ic-bg); margin-top: 10px; outline-offset: 2px; }
.ic-dg:focus-visible { outline: 2px solid var(--ic-accent); }
