.ic-gfilters { z-index: 3; }
.ic-gcell { display: flex; align-items: center; padding: 0 10px; min-width: 0; overflow: hidden; background: inherit; }
.ic-gcell[data-align='right'] { justify-content: flex-end; text-align: right; }
