.ic-gcheck { justify-content: center; padding: 0; background: var(--ic-surface); }
.ic-gbody { position: relative; }
.ic-grow { position: absolute; left: 0; display: grid; align-items: stretch; border-bottom: 1px solid color-mix(in srgb, var(--ic-line) 60%, transparent); background: var(--ic-bg); font-size: 13px; }
