.ic-grow[data-active='true'] { box-shadow: inset 2px 0 var(--ic-accent); }
.ic-dg:not(:focus-visible) .ic-grow[data-active='true'] { box-shadow: none; }
.ic-gfilters .ic-gcell { background: var(--ic-surface); }
.ic-finput { width: 100%; padding: 2px 6px; min-width: 0; font-size: 12px; }
