.ic-pctcell { display: inline-flex; align-items: center; gap: 8px; width: 100%; justify-content: flex-end; }
.ic-pctbar { width: 54px; height: 6px; border-radius: 3px; background: var(--ic-line); overflow: hidden; }
.ic-pctbar > span { display: block; height: 100%; background: var(--ic-c3); }
.ic-spark polyline { stroke: var(--ic-c1); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }
.ic-spark circle { fill: var(--ic-c1); }
.ic-selbar { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 6px 12px; border-radius: 8px; background: color-mix(in srgb, var(--ic-accent) 10%, var(--ic-bg)); font-size: 13px; }
.ic-gempty { position: sticky; left: 24px; padding: 40px 0; display: grid; justify-items: start; gap: 6px; }
.ic-gfoot { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 18px; margin-top: 8px; font-size: 12.5px; }

/* Charts */
.ic-spc, .ic-sankey { position: relative; margin-top: 8px; }
.ic-spc svg, .ic-sankey svg { display: block; overflow: visible; }
.ic-axis-line { stroke: color-mix(in srgb, var(--ic-fg) 9%, transparent); }
.ic-axis-text { fill: var(--ic-muted); font: 11px system-ui, sans-serif; }
