.ic-zone1 { fill: color-mix(in srgb, var(--ic-c3) 11%, transparent); }
.ic-limit { stroke: var(--ic-bad); stroke-width: 1.2; stroke-dasharray: 4 3; opacity: 0.8; }
.ic-center { stroke: var(--ic-fg); stroke-width: 1.3; opacity: 0.55; }
.ic-baseline { fill: color-mix(in srgb, var(--ic-fg) 5%, transparent); }
.ic-marker { stroke: var(--ic-muted); stroke-width: 1; stroke-dasharray: 2 3; }
.ic-series { stroke: var(--ic-c1); stroke-width: 1.6; stroke-linejoin: round; }
.ic-pt { fill: var(--ic-bg); stroke: var(--ic-c1); stroke-width: 1.6; }
.ic-pt[data-signal='true'] { fill: var(--ic-bad); stroke: var(--ic-bg); stroke-width: 1.5; }
