.ic-rule { fill: var(--ic-bad); font: 700 10.5px system-ui, sans-serif; }
.ic-cross { stroke: var(--ic-fg); stroke-width: 1; opacity: 0.3; }
.ic-slink { opacity: 0.32; transition: opacity 0.12s; mix-blend-mode: normal; }
.ic-slink[data-active='false'] { opacity: 0.06; }
.ic-slink:hover { opacity: 0.6; }
.ic-snode { opacity: 0.9; }
.ic-slabel { fill: var(--ic-fg); font: 600 12.5px system-ui, sans-serif; }
.ic g[data-leak='true'] .ic-slabel { fill: var(--ic-bad); }

/* ApprovalQueue */
.ic-queue-body { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 16px; margin-top: 12px; align-items: start; outline-offset: 4px; border-radius: 10px; }
.ic-queue-body:focus-visible { outline: 2px solid var(--ic-accent); }
.ic-qlist { display: grid; gap: 4px; }
.ic-qitem { display: grid; grid-template-columns: 8px minmax(0, 1fr); gap: 10px; align-items: stretch; padding: 8px 10px; border: 1px solid var(--ic-line); border-radius: 10px; cursor: pointer; background: var(--ic-bg); }
.ic-qitem:hover { background: var(--ic-surface); }
.ic-qitem[data-selected='true'] { border-color: var(--ic-accent); box-shadow: 0 0 0 1px var(--ic-accent); }
.ic-qmain { min-width: 0; display: grid; justify-items: start; }
.ic-qtitle { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.3; }
.ic-risk { width: 8px; min-height: 30px; border-radius: 4px; background: var(--ic-good); }
.ic-risk[data-risk='medium'] { background: var(--ic-warn); } .ic-risk[data-risk='high'] { background: var(--ic-bad); }
.ic-qdetail { border: 1px solid var(--ic-line); border-radius: 10px; padding: 14px; min-width: 0; }
.ic-statusline { margin: 4px 0 10px; padding: 6px 10px; border-radius: 8px; background: var(--ic-surface); font-size: 13px; }
.ic-statusline[data-status='stale'], .ic-statusline[data-status='expired'], .ic-statusline[data-status='rejected'] { background: color-mix(in srgb, var(--ic-bad) 10%, var(--ic-bg)); color: var(--ic-bad); }
.ic-statusline[data-status='approved'] { background: color-mix(in srgb, var(--ic-good) 10%, var(--ic-bg)); color: var(--ic-good); }
.ic-qgrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }
.ic-qhead { font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ic-muted); margin-bottom: 4px; }
.ic-evidence { display: grid; gap: 4px; font-size: 13px; }
.ic-evidence li { display: grid; grid-template-columns: 18px 1fr; gap: 4px; }
.ic-evidence li[data-ok='true'] > span:first-child { color: var(--ic-good); } .ic-evidence li[data-ok='false'] > span:first-child { color: var(--ic-bad); font-weight: 700; }
.ic-dlog { display: grid; gap: 3px; font-size: 13px; }
.ic-dlog li[data-ignored='true'] { opacity: 0.7; } .ic-ignored { color: var(--ic-bad); }
.ic-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.ic-btn { font: inherit; font-weight: 600; font-size: 13px; padding: 8px 14px; border-radius: 8px; border: 1px solid var(--ic-line); background: var(--ic-bg); color: var(--ic-fg); cursor: pointer; }
.ic-btn:hover:not(:disabled) { background: var(--ic-surface); }
.ic-btn[data-kind='approve'] { background: var(--ic-accent); color: var(--ic-bg); border-color: var(--ic-accent); }
.ic-btn[data-kind='reject'] { color: var(--ic-bad); border-color: currentColor; }
.ic-btn:disabled { opacity: 0.42; cursor: not-allowed; }
.ic-btn:focus-visible { outline: 2px solid var(--ic-accent); outline-offset: 2px; }
@media (max-width: 760px) { .ic-queue-body { grid-template-columns: 1fr; } }

/* DeadlineGantt */
.ic-gantt { position: relative; margin-top: 8px; overflow-x: auto; }
.ic-gantt svg { display: block; }
.ic-gbar { fill: var(--ic-c1); }
.ic-gbar[data-state='met'] { fill: var(--ic-good); } .ic-gbar[data-state='late'], .ic-gbar[data-state='overdue'] { fill: var(--ic-c1); } .ic-gbar[data-state='remedied'] { fill: var(--ic-warn); }
.ic-gover { fill: url(#ic-hatch); stroke: var(--ic-bad); stroke-width: 1; }
.ic-hatch-bg { fill: color-mix(in srgb, var(--ic-bad) 14%, var(--ic-bg)); } .ic-hatch-line { stroke: var(--ic-bad); stroke-width: 2; }
.ic-diamond { fill: var(--ic-bg); stroke: var(--ic-fg); stroke-width: 1.6; }
.ic-diamond[data-state='overdue'], .ic-diamond[data-state='late'] { stroke: var(--ic-bad); fill: var(--ic-bad); }
.ic-diamond[data-state='met'] { stroke: var(--ic-good); }
.ic-now { stroke: var(--ic-c1); stroke-width: 1.4; stroke-dasharray: 3 3; }
.ic-now-text { fill: var(--ic-c1); font: 700 11px system-ui, sans-serif; }

/* ActivityHeatmap */
.ic-hcell { fill: color-mix(in srgb, var(--ic-fg) 8%, transparent); }
.ic-hcell[data-level='1'], .ic-hcell-sw[data-level='1'] { fill: color-mix(in srgb, var(--ic-c3) 28%, transparent); background: color-mix(in srgb, var(--ic-c3) 28%, transparent); }
.ic-hcell[data-level='2'], .ic-hcell-sw[data-level='2'] { fill: color-mix(in srgb, var(--ic-c3) 50%, transparent); background: color-mix(in srgb, var(--ic-c3) 50%, transparent); }
.ic-hcell[data-level='3'], .ic-hcell-sw[data-level='3'] { fill: color-mix(in srgb, var(--ic-c3) 75%, transparent); background: color-mix(in srgb, var(--ic-c3) 75%, transparent); }
.ic-hcell[data-level='4'], .ic-hcell-sw[data-level='4'] { fill: var(--ic-c3); background: var(--ic-c3); }
.ic-hcell[data-hover='true'] { stroke: var(--ic-fg); stroke-width: 1.5; }
.ic-hbreach { fill: var(--ic-bad); stroke: var(--ic-bg); stroke-width: 1; }
.ic-hlegend { display: flex; align-items: center; gap: 4px; font-size: 12px; color: var(--ic-muted); margin-top: 6px; }
.ic-hcell-sw { display: inline-block; width: 13px; height: 13px; border-radius: 3px; background: color-mix(in srgb, var(--ic-fg) 8%, transparent); }
.ic-hbreach-sw { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--ic-bad); }

.ic-axis-text[data-day='true'] { fill: var(--ic-fg); font-weight: 700; }
.ic-hatch-sw { display: inline-block; width: 16px; height: 10px; border-radius: 2px; border: 1px solid var(--ic-bad); background: repeating-linear-gradient(135deg, var(--ic-bad) 0 2px, transparent 2px 5px); }
.ic-now-sw { display: inline-block; width: 0; height: 12px; border-left: 2px dashed var(--ic-c1); }
.ic-hlegend svg { display: inline-block; }
